def max_product(n):
    # Generate the array
    digits = [0] * n
    for i in range(1, n + 1):
        digits.append(int(digit) + 1)

    # Find the maximum product
    max_product = 0
    for i in range(1, n + 1):
        if i == 0:
            break
        else:
            product = digits[i]
            if i == n:
                max_product = product
                break
    return max_product

