def is_palindrome(s):
    # Store characters that can be replaced
    char_dict = {}
    for char in s:
        if char in char_dict:
            char_dict[char] = True
        else:
            char_dict[char] = False

    # Check if the string is a palindrome
    return char_dict[s] == char_dict[s[::-1]]

