def calculate_total_price(N, M, P):
    # Define the base cases
    if N == 1 or M == 1:
        return 0
    if P == 0:
        return 0

    # Initialize the base cases
    base_case = [0] * (N + 1)
    base_case[0] = P

    # Calculate the minimum price of the set meal
    min_price = min(base_case[1], base_case[2])

    # Calculate the total price of all set meals
    total_price = 0
    for i in range(1, N + 1):
        for j in range(1, M + 1):
            if i == 0 or j == 0:
                return 0
            if base_case[i] == base_case[j]:
                total_price += min_price
            else:
                total_price += base_case[i] * base_case[j]

    return total_price

