def minCost(s):
    # Create a dictionary to store the count of each character
    char_counts = {}

    # Iterate over each character in the string
    for char in s:
        # If the character is not present in the dictionary, add it to the dictionary
        if char not in char_counts:
            char_counts[char] = 1
            char_counts[char] += 1

    # If the character is present in the dictionary, replace it with the character with the least count
    for char, count in char_counts.items():
        if count < min(count, char):
            char_counts[char] = min(count, char)

    return char_counts

