def k_periodic(word, k):
    n = len(word)
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    dp[0][0] = 1
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if i == k and j == k - 1:
                dp[i][j] = dp[i - k - 1][j - k - 1] + dp[i - k - 1][j - k - 1]
    return dp[n][k]

